$:set -euo pipefail
node <<'NODE'
"use strict";
const cp=require("node:child_process");
const REPO="BestNameYet/Terminals";
const prefix="repos/"+REPO+"/";
const oldPath="workspaces/codespace-mcp-srs-design/agents.md";
const newPath="workspaces/codespace-mcp-srs-design/AGENTS.md";
const expectedOld="9712279efd23e3b44cdbc6ef47b594c45788313d";
function call(method,path,payload,allow404=false){
 const args=["api",prefix+path];
 if(method!=="GET") args.push("--method",method);
 if(payload!==undefined)args.push("--input","-");
 const x=cp.spawnSync("gh",args,{input:payload===undefined?undefined:JSON.stringify(payload),encoding:"utf8",timeout:60000,maxBuffer:6*1024*1024});
 if(x.error)throw x.error;
 if(x.status!==0){
   if(allow404&&/404|Not Found/i.test(x.stderr||""))return null;
   throw Error(method+" "+path+" failed: "+(x.stderr||x.stdout||"unknown").slice(0,400));
 }
 return JSON.parse(x.stdout);
}
const current=call("GET","contents/"+oldPath);
if(current.sha!==expectedOld)throw Error("Source content unexpectedly modified; do not overwrite");
if(call("GET","contents/"+newPath,undefined,true)!==null)throw Error("Uppercase target exists");
const initial=Buffer.from(current.content.replace(/\s/g,""),"base64").toString("utf8");
const data=JSON.parse(initial);
if(data.authority.self!==oldPath||!data.authority.entrypoint_order.includes(oldPath))throw Error("Bootstrap self references mismatch");
data.authority.self=newPath;
data.authority.entrypoint_order=data.authority.entrypoint_order.map(p=>p===oldPath?newPath:p);
const revised=JSON.stringify(data,null,2)+"\n";
const before={...data.authority,self:oldPath,entrypoint_order:data.authority.entrypoint_order.map(p=>p===newPath?oldPath:p)};
if(JSON.stringify({...data,authority:before},null,2)+"\n"!==initial)throw Error("Unexpected content changes");
const ref=call("GET","git/ref/heads/main");
const prior=ref.object.sha;
const base=call("GET","git/commits/"+prior);
const tree=call("POST","git/trees",{
 base_tree:base.tree.sha,
 tree:[
  {path:oldPath,mode:"100644",type:"blob",sha:null},
  {path:newPath,mode:"100644",type:"blob",content:revised}
 ]
});
const commit=call("POST","git/commits",{message:"Normalize Codespace MCP bootstrap filename to AGENTS.md",tree:tree.sha,parents:[prior]});
call("PATCH","git/refs/heads/main",{sha:commit.sha,force:false});
const head=call("GET","git/ref/heads/main");
if(head.object.sha!==commit.sha)throw Error("Published branch head mismatch");
const after=call("GET","contents/"+newPath);
const text=Buffer.from(after.content.replace(/\s/g,""),"base64").toString("utf8");
if(text!==revised)throw Error("New AGENTS.md byte mismatch");
if(call("GET","contents/"+oldPath,undefined,true)!==null)throw Error("Lowercase file still exists");
if(JSON.parse(text).tasks.length!==15)throw Error("Task plan mismatch");
console.log(JSON.stringify({status:"RENAMED_AND_VERIFIED",from:oldPath,to:newPath,commit:commit.sha,blob:after.sha,task_count:15,self_reference:JSON.parse(text).authority.self}));
NODE
